(3234127, 453010, 67258, '<td valign="top">As a woman working in a man''s world, I am constantly bashing my head against a glass ceiling, glass walls even - I can relate to this.</td>', 'As a woman working in a man''s world, I am constantly bashing my head against a glass ceiling, glass walls even - I can relate to this.', '2007-01-15 10:09:51.000000', NULL, 1),
(3234147, 453048, 67258, '<td valign="top">Well illustrated!  I sometimes feel I am in a glass box, with all my male ''colleagues'' sitting on the lid and laughing at me through the sides - yep, this photo has hit a bit of a raw nerve!</td>', 'Well illustrated!  I sometimes feel I am in a glass box, with all my male ''colleagues'' sitting on the lid and laughing at me through the sides - yep, this photo has hit a bit of a raw nerve!', '2007-01-15 10:13:23.000000', NULL, 1),
