INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3235015, 452988, 28261, '<td valign="top">Nice simple concept and good use of props/costumes.  Nice clean image sharp, good focus, a bit 2-D and some loss of detail on shirt vs background.<br/> <br/>( 7 )</td>', 'Nice simple concept and good use of props/costumes.  Nice clean image sharp, good focus, a bit 2-D and some loss of detail on shirt vs background. ( 7 )', '2007-01-15 13:43:49.000000', NULL, 1),
(3235029, 453010, 28261, '<td valign="top">A great image that may have benefited from a background fill light to help keep the jacket from blending into the background.  The tie''s pattern makes it look oof which is distracting.  Very nice choice of concept.<br/> <br/>( 7 )</td>', 'A great image that may have benefited from a background fill light to help keep the jacket from blending into the background.  The tie''s pattern makes it look oof which is distracting.  Very nice choice of concept. ( 7 )', '2007-01-15 13:45:46.000000', NULL, 1),
(3235055, 453298, 28261, '<td valign="top">A good concept execution.  Needs slight rotation and highlights blown on top of image create an imbalance.  Some shadows seem murky.  Nice image overall.<br/> <br/>( 6 )</td>', 'A good concept execution.  Needs slight rotation and highlights blown on top of image create an imbalance.  Some shadows seem murky.  Nice image overall. ( 6 )', '2007-01-15 13:52:45.000000', NULL, 1),
(3235059, 452343, 28261, '<td valign="top">Great concept and execution.  Good expressions, emotion within the image!  Slightly closer crop and I would have given a point more.<br/> <br/>( 8 )</td>', 'Great concept and execution.  Good expressions, emotion within the image!  Slightly closer crop and I would have given a point more. ( 8 )', '2007-01-15 13:53:39.000000', NULL, 1),
(3235067, 452865, 28261, '<td valign="top">Image is well captured, but overall lacks strong interest level.  Coloration causes the image to feel flat, not dynamic.  Good sharpness, good motion blur.<br/> <br/>( 6 )</td>', 'Image is well captured, but overall lacks strong interest level.  Coloration causes the image to feel flat, not dynamic.  Good sharpness, good motion blur. ( 6 )', '2007-01-15 13:54:50.000000', NULL, 1),
(3235073, 453079, 28261, '<td valign="top">Vignetting takes away from this image.  Blue/Grey coloration seems out of place.  Great concept and good shot.  Excellent emotion in the image.  Oversharpened.<br/> <br/>( 6 )</td>', 'Vignetting takes away from this image.  Blue/Grey coloration seems out of place.  Great concept and good shot.  Excellent emotion in the image.  Oversharpened. ( 6 )', '2007-01-15 13:55:55.000000', NULL, 1),
(3235088, 453282, 28261, '<td valign="top">While the translation without title is hard, this image is well captured and humorous.  It projects an inside joke between the animals and I would easily come up with this kind of joke.  I like the styling of the finesse as well.<br/> <br/>( 8 )</td>', 'While the translation without title is hard, this image is well captured and humorous.  It projects an inside joke between the animals and I would easily come up with this kind of joke.  I like the styling of the finesse as well. ( 8 )', '2007-01-15 13:59:13.000000', NULL, 1),
(3235093, 453280, 28261, '<td valign="top">While the image does not scream battle of, it can be easily identified with this concept.  The detail of the hands is immense, but overall not a ribbon winner on my judgement.<br/> <br/>( 7 )</td>', 'While the image does not scream battle of, it can be easily identified with this concept.  The detail of the hands is immense, but overall not a ribbon winner on my judgement. ( 7 )', '2007-01-15 14:00:35.000000', NULL, 1),
