(3238873, 452676, 67739, '<td valign="top">I think this is interesting. This is deffinitely not what would have come to my mind first. I love the darl set up. The draping cloth on the bedlike platform adds nice texture to the overall composition. The thing part that makes the most overall difference is the circle in the backdrop. Without it the man would  undoubtedly be less distinguishable.</td>', 'I think this is interesting. This is deffinitely not what would have come to my mind first. I love the darl set up. The draping cloth on the bedlike platform adds nice texture to the overall composition. The thing part that makes the most overall difference is the circle in the backdrop. Without it the man would  undoubtedly be less distinguishable.', '2007-01-16 06:08:05.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3238877, 452427, 67739, '<td valign="top">Iv seen a few shot in this contest that are similar. Maybe its just me but i dont know many couples that fight over the remote.. maybe thats just me. But the photo has a nice commercial sense to it. The even lighting is one major factor in that feel for me. I lso like how you broke up the composition with the upper right corner, its a nice compositional addition.</td>', 'Iv seen a few shot in this contest that are similar. Maybe its just me but i dont know many couples that fight over the remote.. maybe thats just me. But the photo has a nice commercial sense to it. The even lighting is one major factor in that feel for me. I lso like how you broke up the composition with the upper right corner, its a nice compositional addition.', '2007-01-16 06:10:53.000000', NULL, 1),
(3238883, 452614, 67739, '<td valign="top">HAHA gatta love symbolism. My main quarrel is the editing on the right side of the hotdog. That aside i like the focus, choice of DoF, and overall composition.</td>', 'HAHA gatta love symbolism. My main quarrel is the editing on the right side of the hotdog. That aside i like the focus, choice of DoF, and overall composition.', '2007-01-16 06:14:00.000000', NULL, 1),
