(3244570, 452988, 47316, '<td valign="top">Nice image and concept. Bit over-edited for me, especially so where her fingers are.</td>', 'Nice image and concept. Bit over-edited for me, especially so where her fingers are.', '2007-01-17 03:51:48.000000', NULL, 1),
(3244575, 453133, 47316, '<td valign="top">I''m sorry but this doesn''t even look like you tried to make a good image. This really doesn''t convey the theme well and it doesn''t look like there was an attempt to even make the symbols look good.</td>', 'I''m sorry but this doesn''t even look like you tried to make a good image. This really doesn''t convey the theme well and it doesn''t look like there was an attempt to even make the symbols look good.', '2007-01-17 03:53:31.000000', NULL, 1),
